using Microsoft.ML;
using ChurnPredictor.Models;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// Train the model at startup
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(app.Environment.ContentRootPath, "Data", "customers.csv");

var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(
    dataPath, hasHeader: true, separatorChar: ',');

var pipeline = mlContext.Transforms.Categorical
        .OneHotEncoding("RegionEncoded", "Region")
    .Append(mlContext.Transforms.Concatenate("Features",
        "Age", "Income", "RegionEncoded", "PurchaseHistory"))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers
        .SdcaLogisticRegression());

var model = pipeline.Fit(dataView);

// Evaluate
var predictions = model.Transform(dataView);
var metrics = mlContext.BinaryClassification.Evaluate(predictions);
Console.WriteLine($"Accuracy: {metrics.Accuracy:P2}");
Console.WriteLine($"AUC:      {metrics.AreaUnderRocCurve:P2}");
Console.WriteLine($"F1 Score: {metrics.F1Score:P2}");

var predictionEngine = mlContext.Model
    .CreatePredictionEngine<CustomerData, ChurnPrediction>(model);

app.MapGet("/", () => "Churn Predictor API — POST /predict with customer JSON");

app.MapPost("/predict", (CustomerData customer) =>
{
    var result = predictionEngine.Predict(customer);
    return Results.Ok(new
    {
        WillChurn = result.Churned,
        result.Probability,
        result.Score
    });
});

app.Run();

